bool same(const SourceRef&a,const SourceRef&b){return a.domain==b.domain&&a.kind==b.kind&&a.id==b.id;}
bool same(const ConsumerRef&a,const ConsumerRef&b){return a.domain==b.domain&&a.kind==b.kind&&a.id==b.id&&a.slot==b.slot;}
bool present(const SourceRef&s){return !s.domain.empty()&&!s.kind.empty()&&!s.id.empty();}
